from .models import (
    CatalogError,
    Category,
    Food,
    Invalid,
    Missing,
    Product,
    Restock,
    Tool,
)
from .runtime import Err, Ok, Result, Table, div, rem


def price_label(cents: int) -> str:
    """The price as dollars and cents."""
    dollars = div(cents, 100)
    rest = rem(cents, 100)
    if rest < 10:
        pad = "0"
    else:
        pad = ""
    return f"${dollars}.{pad}{rest}"


def category_of(p: Product) -> Category:
    if "tool" in p.tags:
        return Tool(heavy="heavy" in p.tags)
    return Food()


def add_product(
    input: Product, products: Table[Product]
) -> Result[Product, CatalogError]:
    match products.get(input.sku):
        case Product() as p:
            return Err(Invalid(reason=f"duplicate sku {p.sku}"))
        case None:
            return Ok(products.save(input))


def get_product(sku: str, products: Table[Product]) -> Result[Product, CatalogError]:
    match products.get(sku):
        case Product() as p:
            return Ok(p)
        case None:
            return Err(Missing(sku=sku))


def list_products(
    tag: str | None, page: int, per_page: int, products: Table[Product]
) -> list[Product]:
    all_ = sorted(products.scan(), key=lambda p: p.sku)
    match tag:
        case str() as t:
            tagged = [p for p in all_ if t in p.tags]
        case None:
            tagged = all_
    start = (page - 1) * per_page
    return tagged[start : start + per_page]


def restock(
    sku: str, input: Restock, products: Table[Product]
) -> Result[Product, CatalogError]:
    result = find(sku, products)
    if isinstance(result, Err):
        return result
    p = result.value
    p = p.model_copy(update={"stock": p.stock + input.amount})
    return Ok(products.save(p))


def find(sku: str, products: Table[Product]) -> Result[Product, CatalogError]:
    match products.get(sku):
        case Product() as p:
            return Ok(p)
        case None:
            return Err(Missing(sku=sku))


def price_table(products: Table[Product]) -> dict[str, str]:
    return {p.sku: price_label(p.cents) for p in products.scan()}


def delete_product(sku: str, products: Table[Product]) -> bool:
    return products.delete(sku)


def average_cents(skus: str, products: Table[Product]) -> int:
    wanted = skus.split(",")
    found = [p for p in products.scan() if p.sku in wanted]
    return div(sum([p.cents for p in found]), len(found))
